TLM.f("Sancti/09-19",{"officium":"S. Januarii Episcopi et Sociorum Martyrum","rule":["vide C3b;","9 lectiones"],"fallback":"Commune/C3b","from":{"Introitus":"Commune/C3b","Lectio":"Commune/C3b","Graduale":"Commune/C3b","Tractus":"Commune/C3b","Offertorium":"Commune/C3b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua sanctórum Mártyrum tuórum Januárii et Sociórum ejus sollemnitáte lætíficas: concéde propítius; ut, quorum gaudémus méritis, accendámur exémplis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 24:3-13"},{"k":"text","la":"In illo témpore: Sedénte Jesu super montem Olivéti, accessérunt ad eum discípuli secréto, dicéntes: Dic nobis, quando hæc erunt? et quod signum advéntus tui et consummatiónis sǽculi? Et respóndens Jesus, dixit eis: Vidéte, ne quis vos sedúcat. Multi enim vénient in nómine meo, dicéntes: Ego sum Christus: et multos sedúcent. Auditúri enim estis prælia et opiniónes prœliórum. Vidéte, ne turbémini. Opórtet enim hæc fíeri, sed nondum est finis. Consúrget enim gens in gentem, et regnum in regnum, et erunt pestiléntiæ et fames et terræmótus per loca. Hæc autem ómnia inítia sunt dolórum. Tunc tradent vos in tribulatiónem et occídent vos: et éritis odio ómnibus géntibus propter nomen meum. Et tunc scandalizabúntur multi, et ínvicem tradent, et odio habébunt ínvicem. Et multi pseudoprophétæ surgent, et sedúcent multos. Et quóniam abundávit iníquitas, refrigéscet cáritas multórum. Qui autem perseveráverit usque in finem, hic salvus erit."}],"Offertorium":[{"k":"ref","la":"Sap 3:1-3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiae: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."}],"Secreta":[{"k":"text","la":"Oblátis, quǽsumus, Dómine, placáre munéribus: et, intercedéntibus sanctis Martýribus tuis Januário et Sóciis ejus, a cunctis nos defénde perículis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedéntibus sanctis Martýribus tuis Januário et Sóciis ejus, coeléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"be7e83b3647261b8":{"t":"Ps 36, 39, Ps 36, 1\n(Ps 36, 39) Spasenje pravednika dolazi od Gospodina. On je njihovo utočište u vrijeme nevolje. (Ps 36, 1) Nemoj zaviđati sreći zlotvora, niti se uznemiravati radi zadovoljstva grešnika.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 39) Spasenje pravednika dolazi od Gospodina. On je njihovo utočište u vrijeme nevolje.","kn":"(Ps. 36, 39). U Gospodinu je spas pravednika; Gospodin je njihovo utočište u nevolji. (Ps. 36, 1) Misa »Štiti me« za mučenike Ne zaviđaj sreći grješnika i zlotvora! Slava Ocu . . . U Gospodinu ...","knRef":"Kniewald 1942, str. 800–801 (snimka 401) (OCR)"},"901fb07fd65d3134":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom svojih svetih mučenika Januarija i njegovih drugova, daj milostivo da nas oduševe primjeri onih kojih se zaslugama radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, milostivi Bože, koji nas razveseljuješ godišnjom svetkovinom Tvojih svetih mučenika I. i I., da nas rasplamte njihovi primjeri, kao što nas razveseljuju njihove zasluge. Po G. n.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"},"e1975ee9d370e316":{"t":"Heb 10, 32-38\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, sjetite se onih prvih dana, kada ste prosvijetljeni podnijeli teške borbe i patnje. Sad ste bili izloženi pogrdama i nevoljama, sad opet postali dionicima onih, koji su već doživjeli isto. Vi ste bili milosrdni prema zatočenicima i vedro gledajući podnijeli ste kada su vam otimali vaša dobra, jer ste znali da imate bolji i trajni imutak. Stoga ne gubite pouzdanje, za koje ćete primiti obilnu nagradu. Treba vam strpljivosti, da vršeći Božju volju postignete obećanje. Da, još vrlo malo i doći će onaj koji ima doći i neće zakasniti. A moj pravednik živi od vjere.","kn":"Čitanje poslanice bi. Pavla apostola Hebrejima (10, 32-38). Braćo! Sjetite se onih prvih dana, kad ste prosvijetljeni (podnijeli tešku borbu patnja. Amo ste bili izloženi pogrdama i nevoljama, a tamo ste postali sudionicima onih, koji su isto doživjeli. Vi ste bili samilosni prema zatočenicima i s radošću ste podnijeli, kad su oteli vaša dobra, jer ste znali, da imate bolji i trajni imetak. Zato ne odbacujte svoga pouzdanja, koje će biti obilno nagrađeno. Treba vam strpljivosti, da postignete obećanje vršeći volju Božju. Jer još nešto malo i doći će onaj, koji ima doći, i ne će kasniti. A moj pravednik živi od vjere.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"},"20fe01eb04b0f5d5":{"t":"Ps 33, 18-19\nZavapiše pravednici i Gospodin ih usliša, i izbavi ih iz svih nevolja njihovih. Gospodin je blizu onima koji su skrušena srca. On spašava ponizne duhom.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nTebe, Gospodine, hvali svjetla vojska mučenika. <i>Aleluja</i>.","kn":"(Ps. 33, 18, 19). Zavapiše pravednici i Gospodin ih je uslišao i izbavio ih je od svih nevolja. Blizu je Gospodin onima, koji su skrušena srca i spasit će one, koji su ponizni duhorn.\n\nAleluja, aleluja! Tebe, Gospodine, svijetla mučenička hvali vojiska.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"6ecc60f6ebb5a515":{"t":"Mt 24, 3-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme kad je Isus sjedio ma Maslinskoj gori, pristupiše k njemu samo njegovi učenici i rekoše: Reci nam kad će to biti? Koji je znak:tvoga dolaska i svršetka svijeta? Isus im odgovori: Gledajte da vas tko ne zavede, jer će mnogi doći u moje ime i govoriti: Ja sam Krist. I mnoge će zavesti. Čut ćete za radove i glasove o njima. Pazite da se ne zbunite, jer sve to mora biti, ali još nije svršetak. Tada će ustati narod na narod i kraljevstvo na kraljevstvo, i bit će kuga i glad i potresi. A to je sve početak nevolja. Tada će vas predati na muke i ubijat će vas. Svi će narodi zamrziti na vas radi moga imena. Tada će mnogi zalutati u vjeri i jedan će drugoga zamrziti. I ustat će mnogi krivi proroci i zavest će mnoge. Ljubav će kod mnogih ohladnjeti, jer će bezbožnost preuzeti mah. A tko ustraje do kraja spasit će se.","kn":"t Slijedi sv. evanđelje po Mateju (24, 3-13). U ono vrijeme, kad je Isus sjedio na gori Maslinskoj, pristupiš© k njemu učenici nasamo, govoreći: Reci nam, kad će to biti? i koji je znak tvojega dolaska, i svršetka svijeta? I odgovarajući Isus reče im: Gledajte, da vas tko ne zavede. Jer će mnogi doći u ime moje govoreći: Ja sam Krist: i mno<ge će zavesti. Cut ćete raitove, i giasove o ratovima. Gledajte, da se ne zbunite. Jer treba da to sve bude, ali još nije svršetak. Tada će ustati narod na narod, i kraljevstvo na kraljevstvo, i bit će kuga, i glad, i potresi po mjestima. A to je sve početak nevoljama. Tada će vas predati na muke, i ubijati će vas: i svi će narodi zamrziti na vas radi imena moga. I tada će se mnogi sablazniti, i jedan će na drugoga zamrziti. I ustat će mnogi krivi proroci, i zavesti će mnoge. I što će se bezakonje umnožiti, ohladnjet će ljubav mnogih. A koji ustraje do kraja, onaj će se spasiti.","knRef":"Kniewald 1942, str. 714–715 (snimka 358) (OCR)"},"a7438b09133fada7":{"t":"Mudr 3, 1 i 2 i 3\nDuše su pravednika u Božjoj ruci, i neće ih se dotaći muka zlobnika; očima se luđaka činilo da umiru, a oni su u miru, <i>aleluja</i>.","kn":"(Mudr. 3, 1-3). Duše su pravednika u ruci Božjoj, i ne će ih se dotaći muka zlobe; činilo se luđačkim očima, da umirii, a oni su u miru. Aleluja.","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"7578cc87a56523bf":{"t":"Ublaži se, molimo, Gospodine, prikaznim darovima i po zagovoru tvojih svetih mučenika Januarija i njegovih drugova brani nas od svih pogibelji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":". Neka Te ublaže. Gospodine, prineseni darovi, da nas zagovorom Tvojih svetih mučenika I. i I. braniš od svih pogibli. Po G. n.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"080d978e8249bb86":{"t":"Mt 10, 27\nŠto vam kažem u tami, razglasujte na svjetlu, kaže Gospodin, i ono što vam na uho šapćem, propovijedajte s krovova. <i>Aleluja</i>.","v":"aleluia → ∅","kn":"(Mt. 10, 27). Što vam govorim u tami, ka'Zujte na svjetlosti, veli Gosjpodin; i što na uho čujete, propovijedajte na krovovima, aleluja.","knRef":"Kniewald 1942, str. 562–563 (snimka 282) (OCR)"},"a90225add84055ab":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, ova Pričest očisti od opačina i po zagovoru svetih tvojih mučenika Januarija i njegovih drugova, učini dionicima nebeske pomoći.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova nas. Gospodine, pričest očistila od grijeha i zagovorom svetih mučenika I. i I. učinila dionicima nebeskog spasenja. Po G. n.","knRef":"Kniewald 1942, str. 802–803 (snimka 402) (OCR)"}}});
